import hashlib,json,re,sys
from pathlib import Path
source,out=map(Path,sys.argv[1:])
raw=source.read_bytes()
sha=hashlib.sha256(raw).hexdigest()
assert sha=='a6d3f9b0dfbebd1cb1dd5b9bc98df9c666e04a1ca3c6edbf48dc7d3835fd6efa'
def scope(obj):
    if isinstance(obj,dict):
        for key,value in obj.items():
            if key in {'title','description','name'} and isinstance(value,str):
                yield value
            elif isinstance(value,(dict,list)):
                yield from scope(value)
    elif isinstance(obj,list):
        for value in obj:
            yield from scope(value)
pattern=re.compile(r'\bcsv\b|\bcomma.separated\b|\bdata\s+(migration|cleansing|cleaning|validation|quality|conversion|import|reconciliation)\b|\bspreadsheet\b|\bfile\s+(validation|conversion)\b',re.I)
releases=json.loads(raw)['releases']
assert len(releases)==25
rows=[]
for release in releases:
    tender=release.get('tender') or {}
    fields=list(scope(tender))
    rows.append({'id':release.get('id'),'title':tender.get('title'),'lots':len(tender.get('lots') or []),'text_fields_screened':len(fields),'matched_terms':sorted(set(match.group(0) for field in fields for match in pattern.finditer(field)))})
hits=[row for row in rows if row['matched_terms']]
report={'source':'https://www.find-tender.service.gov.uk/api/1.0/ocdsReleasePackages?stages=tender&limit=25','source_sha256':sha,'fetch_receipt':'TASK-179540820101','scope':'One page of 25 releases. Screened nested tender titles, descriptions and names, including lot fields. A textual match is a pointer. Unpublished tender packs and other pages were outside coverage.','rows':rows,'candidate_pointers':hits,'decision':'No concrete lead for separately priced remote CSV validation or migration QA in this page' if not hits else 'Read matching scope before making a bid decision','reopen':'A live original notice explicitly permitting an independently quotable remote CSV validation or migration QA deliverable. Verify eligibility and settlement before a submission-ready quote.','market_demand':'unknown','buyer_specific_controls':'Not run because no original acceptance requirement was identified in the earlier scope review.','submission':'none'}
out.write_text(json.dumps(report,indent=2,ensure_ascii=False)+'\n')
print(json.dumps({'releases':len(rows),'lots':sum(r['lots'] for r in rows),'text_fields':sum(r['text_fields_screened'] for r in rows),'pointers':hits},ensure_ascii=False))
